+// API keys, roles and the audit trail. Keys live in the data as `apiKeys`.
+import { AppError } from "../errors.js";
+
+/** Roles from least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Routes (as "METHOD pattern") a cook may use besides reading.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reads only managers may make.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** The API key record for an `Authorization: Bearer <key>` header, or throws `unauthorized`. */
+export function authenticate(store, header) {
+  const m = /^Bearer\s+(\S+)$/i.exec(String(header ?? "").trim());
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless `role` may call `method` on the route `pattern`. */
+export function authorize(role, method, pattern) {
+  const route = `${method} ${pattern}`;
+  const ok =
+    role === "manager" ||
+    (method === "GET" && !MANAGER_READS.has(route) && ROLES.includes(role)) ||
+    (role === "cook" && COOK_ROUTES.has(route));
+  if (!ok) throw new AppError("forbidden", { role, action: route });
+}
+
+/** Appends an audit entry for a request that may change data. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit.push({ at, key, method, path, status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return store.data.audit.map((e, i) => ({ e, i })).sort((a, b) => b.e.at.localeCompare(a.e.at) || b.i - a.i).map((x) => x.e);
+}
