diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..e341d1e
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,50 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, KEYS, NOW } from "./helpers.js";
+
+const bearer = (k) => ({ authorization: `Bearer ${k}` });
+
+test("missing or unknown keys are 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await raw({ path: "/items", headers: bearer("nope") });
+  assert.equal(bad.status, 401);
+});
+
+test("viewers only read", async () => {
+  const { raw } = app();
+  assert.equal((await raw({ path: "/items", headers: bearer(KEYS.viewer) })).status, 200);
+  const res = await raw({ method: "POST", path: "/recipes/1/cook", headers: bearer(KEYS.viewer), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+});
+
+test("cooks cook but cannot order, and managers can", async () => {
+  const { raw } = app();
+  const cook = await raw({ method: "POST", path: "/recipes/1/cook", headers: bearer(KEYS.cook), body: { portions: 1 } });
+  assert.equal(cook.status, 200);
+  const order = await raw({ method: "POST", path: "/orders/1/send", headers: bearer(KEYS.cook) });
+  assert.equal(order.status, 403);
+  const stocktake = await raw({ method: "POST", path: "/stocktakes", headers: bearer(KEYS.cook), body: { location: "dry" } });
+  assert.equal(stocktake.status, 403);
+  const mgr = await raw({ method: "POST", path: "/stocktakes", headers: bearer(KEYS.manager), body: { location: "dry" } });
+  assert.equal(mgr.status, 201);
+});
+
+test("changes are audited and GET /audit is for managers, newest first", async () => {
+  const { raw, store } = app();
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: bearer(KEYS.cook), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/orders/1/send", headers: bearer(KEYS.cook) });
+  await raw({ path: "/items", headers: bearer(KEYS.cook) });
+  assert.equal(store.data.audit.length, 2);
+  assert.equal((await raw({ path: "/audit", headers: bearer(KEYS.cook) })).status, 403);
+  const list = await raw({ path: "/audit", headers: bearer(KEYS.manager) });
+  assert.equal(list.status, 200);
+  assert.deepEqual(list.body.map((e) => [e.key, e.method, e.path, e.status]), [
+    ["line-cook", "POST", "/orders/1/send", 403],
+    ["line-cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.equal(list.body[0].at, new Date(NOW).toISOString());
+});
